import{_ as i,C as t,o as d,c,a2 as o,E as n}from"./chunks/framework.CdvW4CUT.js";const y=JSON.parse('{"title":"Connect the agent","description":"","frontmatter":{"title":"Connect the agent"},"headers":[],"relativePath":"en/agent/connecter.md","filePath":"en/agent/connecter.md"}'),h={name:"en/agent/connecter.md"};function l(u,e,p,g,m,_){const a=t("Ask"),s=t("AskExample"),r=t("Capture");return d(),c("div",null,[e[0]||(e[0]=o('<h1 id="connect-the-agent" tabindex="-1">Connect the agent <a class="header-anchor" href="#connect-the-agent" aria-label="Permalink to &quot;Connect the agent&quot;">​</a></h1><p>This journey connects your assistant to Kessho, then checks that it sees the memory. You do it once per machine; the screen itself is described in <a href="/en/guide/agents.html">Connect your agents</a>.</p><h2 id="what-you-ask-the-agent" tabindex="-1">What you ask the agent <a class="header-anchor" href="#what-you-ask-the-agent" aria-label="Permalink to &quot;What you ask the agent&quot;">​</a></h2><p>Connecting a client is a gesture of the <strong>application</strong>, not of the agent: no MCP tool deploys anything. Once the client is connected, you check with two requests.</p>',4)),n(a,{say:"Which tools does Kessho give me?",verb:"mem_help",family:"maintenance"}),n(s,{tool:"mem_list"}),e[1]||(e[1]=o('<h2 id="what-the-application-does" tabindex="-1">What the application does <a class="header-anchor" href="#what-the-application-does" aria-label="Permalink to &quot;What the application does&quot;">​</a></h2><p>When you click <strong>Auto-inject</strong> (or, at first launch, <strong>Declare Kessho to my assistants</strong>), Kessho handles all detected clients at once. For each one:</p><ol><li>it backs up the configuration file, then writes an entry named <code>kessho</code> that starts its server, with no argument and no permission;</li><li>if that declaration succeeded, it drops the client&#39;s <strong>procedures</strong> when it has any (see below).</li></ol><p>The ten clients, and what Kessho writes into each:</p><table tabindex="0"><thead><tr><th>Client</th><th>Server declaration</th><th>Procedures dropped under</th></tr></thead><tbody><tr><td>Claude Code</td><td><code>~/.claude.json</code></td><td><code>~/.claude/</code> (or <code>$CLAUDE_CONFIG_DIR</code>)</td></tr><tr><td>GitHub Copilot CLI</td><td><code>~/.copilot/mcp-config.json</code></td><td><code>~/.copilot/</code> (or <code>$COPILOT_HOME</code>)</td></tr><tr><td>Codex</td><td><code>~/.codex/config.toml</code></td><td><code>~/.codex/</code></td></tr><tr><td>Gemini CLI</td><td><code>~/.gemini/settings.json</code></td><td><code>~/.gemini/</code></td></tr><tr><td>Mistral Vibe</td><td><code>~/.vibe/config.toml</code></td><td><code>~/.vibe/</code></td></tr><tr><td>Claude Desktop</td><td><code>~/Library/Application Support/Claude/claude_desktop_config.json</code> (macOS)</td><td>none</td></tr><tr><td>opencode</td><td><code>~/.config/opencode/opencode.json</code></td><td>none</td></tr><tr><td>Antigravity, Antigravity (application), Antigravity (CLI)</td><td><code>~/.gemini/config/mcp_config.json</code>, <code>~/.gemini/antigravity/mcp_config.json</code>, <code>~/.gemini/antigravity-cli/mcp_config.json</code></td><td>none</td></tr></tbody></table><p>&quot;None&quot; means: the server is declared and the agent sees the tools, but Kessho drops nothing that tells it <strong>when</strong> to call them. The code states this explicitly, in its list of clients without procedures (<code>SANS_PROCEDURES</code>): for Claude Desktop and opencode, the place where these clients would read procedures is not established; for Antigravity, it has never been measured. With these clients, it is up to you to ask for the tool (&quot;call <code>mem_recall</code> on kessho-docs&quot;).</p><h3 id="the-procedures" tabindex="-1">The procedures <a class="header-anchor" href="#the-procedures" aria-label="Permalink to &quot;The procedures&quot;">​</a></h3><p>These are files (skills, commands) that the client reads: one per tool or gesture, for example <code>mem-recall</code> or <code>mem-archive</code>. They tell the agent <strong>when</strong> to call the tool, without you typing a command:</p><ul><li>a wish to resume (&quot;let&#39;s pick up&quot;, &quot;where were we?&quot;) or a question about the past (&quot;what did we decide?&quot;) triggers the resume, see <a href="/en/agent/reprendre.html">Resume a project</a>;</li><li>an end signal (&quot;we&#39;re stopping&quot;, &quot;I&#39;m done&quot;) triggers the full archive, see <a href="/en/agent/archiver.html">Archive a session</a>;</li><li>the others (search, note, rename, sync…) trigger on the intent you express.</li></ul><p>A procedure you have edited by hand is <strong>never overwritten</strong>: Kessho leaves it in place and the screen flags it (&quot;modifiée à la main&quot;, written in French). The procedures Kessho dropped itself are updated at the next deployment.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2>',11)),n(r,{name:"connecteurs",alt:"The MCP agent connectors after “Auto-inject”: every detected client has moved to “Deployed”."}),e[2]||(e[2]=o('<ul><li><strong>Settings › MCP connectors</strong>: the table of clients with their <strong>State</strong> (<strong>Deployed</strong>, <strong>To configure</strong>, <strong>Not detected</strong>…), the <strong>Probe the server</strong>, <strong>Auto-inject</strong> and <strong>Uninstall</strong> buttons, and the <strong>Deployment</strong> panel. The labels are explained in <a href="/en/guide/agents.html">Connect your agents</a>.</li><li><strong>Probe the server</strong> measures Kessho&#39;s server (&quot;Server reachable · 42 ms&quot;). It does <strong>not</strong> say that an assistant uses it: for that, ask the agent for a tool (the two requests above) and see whether it answers with your projects.</li><li>The status bar shows <strong>AGENTS 8/8</strong> in the capture above (the figure depends on your machine): how many detected clients carry Kessho.</li><li>Under a client, the screen lists the procedures removed or spared, if any.</li></ul>',1))])}const b=i(h,[["render",l]]);export{y as __pageData,b as default};
